"""
Project 018: Simple Todo CLI
Category: CLI & Utilities
Description: Manage a simple to-do list in memory during the session.
"""

def run_project_18():
    print("=" * 45)
    print("        PYTHON PROJECT 018: SIMPLE TODO CLI")
    print("=" * 45)

    todos = []

    while True:
        print("\n--- To-Do Menu ---")
        print("1. View Tasks")
        print("2. Add Task")
        print("3. Remove Task")
        print("4. Exit")

        choice = input("Select an option (1-4): ").strip()

        if choice == '1':
            if not todos:
                print("Your to-do list is empty.")
            else:
                for i, task in enumerate(todos, 1):
                    print(f"{i}. {task}")
        elif choice == '2':
            task = input("Enter the new task: ").strip()
            if task:
                todos.append(task)
                print("Task added!")
        elif choice == '3':
            try:
                index = int(input("Enter task number to remove: ")) - 1
                if 0 <= index < len(todos):
                    removed = todos.pop(index)
                    print(f"Removed task: {removed}")
                else:
                    print("Invalid task number.")
            except ValueError:
                print("Please enter a valid number.")
        elif choice == '4':
            print("Exiting To-Do CLI. Goodbye!")
            break
        else:
            print("Invalid choice. Please select 1-4.")

    return True

if __name__ == "__main__":
    run_project_18()

"""
Project 021: Pythagorean Triplet Finder
Category: Math & Logic
Description: Find Pythagorean triplets up to a given limit.
"""

def run_project_21():
    print("=" * 45)
    print("  PYTHON PROJECT 021: PYTHAGOREAN TRIPLETS")
    print("=" * 45)

    try:
        limit = int(input("Enter a limit for the hypotenuse: "))

        if limit < 5:
            print("Limit must be at least 5.")
            return False

        triplets = []
        for c in range(5, limit + 1):
            for b in range(4, c):
                for a in range(3, b):
                    if a*a + b*b == c*c:
                        triplets.append((a, b, c))

        print(f"\nPythagorean triplets up to c={limit}:")
        for t in triplets:
            print(f"{t[0]}^2 + {t[1]}^2 = {t[2]}^2")

        return True
    except ValueError:
        print("Invalid input.")
        return False

if __name__ == "__main__":
    run_project_21()

"""
Project 030: File Extension Organizer
Category: File Handling
Description: Analyze extensions in a directory (simulation).
"""
import os

def run_project_30():
    print("=" * 45)
    print("    PYTHON PROJECT 030: EXTENSION ORGANIZER")
    print("=" * 45)

    folder = input("Enter directory path to analyze (or '.' for current): ").strip()

    if not os.path.isdir(folder):
        print("Invalid directory path.")
        return False

    ext_count = {}
    try:
        for item in os.listdir(folder):
            if os.path.isfile(os.path.join(folder, item)):
                _, ext = os.path.splitext(item)
                ext = ext.lower() if ext else "No Extension"
                ext_count[ext] = ext_count.get(ext, 0) + 1

        print("\n--- File Extensions Found ---")
        for ext, count in sorted(ext_count.items()):
            print(f"{ext}: {count} file(s)")

        return True
    except Exception as e:
        print(f"Error accessing directory: {e}")
        return False

if __name__ == "__main__":
    run_project_30()

"""
Project 037: Basic Contact List CLI
Category: CLI & Utilities
Description: Store and retrieve simple contacts during the session.
"""

def run_project_37():
    print("=" * 45)
    print("    PYTHON PROJECT 037: BASIC CONTACT LIST")
    print("=" * 45)

    contacts = {}

    while True:
        print("\n--- Menu ---")
        print("1. Add/Update Contact")
        print("2. Search Contact")
        print("3. List All Contacts")
        print("4. Exit")

        choice = input("Select an option (1-4): ").strip()

        if choice == '1':
            name = input("Name: ").strip()
            phone = input("Phone: ").strip()
            contacts[name] = phone
            print(f"Contact '{name}' saved.")
        elif choice == '2':
            name = input("Search Name: ").strip()
            if name in contacts:
                print(f"Phone: {contacts[name]}")
            else:
                print("Contact not found.")
        elif choice == '3':
            if not contacts:
                print("Contact list is empty.")
            else:
                for name, phone in sorted(contacts.items()):
                    print(f"{name}: {phone}")
        elif choice == '4':
            print("Goodbye!")
            break
        else:
            print("Invalid choice.")

    return True

if __name__ == "__main__":
    run_project_37()

"""
Project 044: Simple Grade Calculator
Category: Utilities
Description: Calculate average grade and letter grade from a list.
"""

def run_project_44():
    print("=" * 45)
    print("     PYTHON PROJECT 044: GRADE CALCULATOR")
    print("=" * 45)

    try:
        grades_str = input("Enter grades separated by spaces: ").strip()
        if not grades_str:
            return False

        grades = [float(g) for g in grades_str.split()]
        avg = sum(grades) / len(grades)

        if avg >= 90:
            letter = 'A'
        elif avg >= 80:
            letter = 'B'
        elif avg >= 70:
            letter = 'C'
        elif avg >= 60:
            letter = 'D'
        else:
            letter = 'F'

        print(f"\nAverage: {avg:.2f}")
        print(f"Letter Grade: {letter}")
        return True
    except ValueError:
        print("Invalid input.")
        return False

if __name__ == "__main__":
    run_project_44()

"""
Project 049: Folder Empty Cleaner
Category: File Handling
Description: Check for empty folders (simulated).
"""
import os

def run_project_49():
    print("=" * 45)
    print("     PYTHON PROJECT 049: EMPTY FOLDER SCANNER")
    print("=" * 45)

    folder = input("Enter directory path to scan (or '.' for current): ").strip()

    if not os.path.isdir(folder):
        print("Invalid directory path.")
        return False

    empty_folders = []
    try:
        for root, dirs, files in os.walk(folder):
            if not dirs and not files:
                empty_folders.append(root)

        if empty_folders:
            print("\nFound empty folders:")
            for f in empty_folders:
                print(f)
        else:
            print("\nNo empty folders found.")

        return True
    except Exception as e:
        print(f"Error accessing directory: {e}")
        return False

if __name__ == "__main__":
    run_project_49()

"""
Project 060: Basic Password Strength Meter
Category: Security & Text
Description: Check password strength based on length, digits, and cases.
"""

def run_project_60():
    print("=" * 45)
    print("    PYTHON PROJECT 060: PASSWORD STRENGTH")
    print("=" * 45)

    pwd = input("Enter a password to test: ")

    score = 0
    if len(pwd) >= 8:
        score += 1
    if any(c.isupper() for c in pwd):
        score += 1
    if any(c.islower() for c in pwd):
        score += 1
    if any(c.isdigit() for c in pwd):
        score += 1
    if any(c in "!@#$%^&*()-_+=<>?/\\|~{}[]," for c in pwd):
        score += 1

    print("\n--- Result ---")
    if score < 3:
        print("Strength: Weak")
    elif score < 5:
        print("Strength: Medium")
    else:
        print("Strength: Strong")

    return True

if __name__ == "__main__":
    run_project_60()

"""
Project 061: Simple Shopping Cart
Category: CLI & Utilities
Description: A basic CLI shopping cart system.
"""

def run_project_61():
    print("=" * 45)
    print("      PYTHON PROJECT 061: SHOPPING CART")
    print("=" * 45)

    cart = {}

    while True:
        print("\n--- Cart Menu ---")
        print("1. Add Item")
        print("2. Remove Item")
        print("3. View Cart & Total")
        print("4. Checkout (Exit)")

        choice = input("Select an option (1-4): ").strip()

        if choice == '1':
            item = input("Item Name: ").strip().title()
            try:
                price = float(input("Price: $"))
                cart[item] = cart.get(item, 0) + price
                print(f"Added {item} for ${price:.2f}")
            except ValueError:
                print("Invalid price.")
        elif choice == '2':
            item = input("Item Name to remove: ").strip().title()
            if item in cart:
                del cart[item]
                print(f"Removed {item}")
            else:
                print("Item not found in cart.")
        elif choice == '3':
            if not cart:
                print("Cart is empty.")
            else:
                print("\n--- Current Cart ---")
                total = 0
                for item, price in cart.items():
                    print(f"{item}: ${price:.2f}")
                    total += price
                print(f"Total: ${total:.2f}")
        elif choice == '4':
            print("Checking out... Thank you for shopping!")
            break
        else:
            print("Invalid choice.")

    return True

if __name__ == "__main__":
    run_project_61()

"""
Project 066: Basic Habit Tracker CLI
Category: CLI & Utilities
Description: Simple daily habit checklist during a session.
"""

def run_project_66():
    print("=" * 45)
    print("     PYTHON PROJECT 066: BASIC HABIT TRACKER")
    print("=" * 45)

    habits = ["Drink Water", "Exercise", "Read 10 Pages", "Meditate"]
    status = {h: False for h in habits}

    while True:
        print("\n--- Daily Habits ---")
        for i, h in enumerate(habits, 1):
            check = "[X]" if status[h] else "[ ]"
            print(f"{i}. {check} {h}")

        print("5. Exit")

        choice = input("\nEnter number to toggle status (or 5 to exit): ").strip()

        if choice == '5':
            break

        try:
            idx = int(choice) - 1
            if 0 <= idx < len(habits):
                habit_name = habits[idx]
                status[habit_name] = not status[habit_name]
            else:
                print("Invalid number.")
        except ValueError:
            print("Please enter a valid number.")

    return True

if __name__ == "__main__":
    run_project_66()

"""
Project 084: Simple Inventory Tracker
Category: CLI & Utilities
Description: Track items and quantities.
"""

def run_project_84():
    print("=" * 45)
    print("     PYTHON PROJECT 084: INVENTORY TRACKER")
    print("=" * 45)

    inventory = {}

    while True:
        print("\n1. Add/Update Item")
        print("2. Remove Item")
        print("3. View Inventory")
        print("4. Exit")

        choice = input("Choice: ").strip()

        if choice == '1':
            item = input("Item Name: ").title()
            try:
                qty = int(input("Quantity: "))
                inventory[item] = inventory.get(item, 0) + qty
                print(f"Updated {item}.")
            except ValueError:
                print("Invalid quantity.")
        elif choice == '2':
            item = input("Item to remove: ").title()
            if item in inventory:
                del inventory[item]
                print(f"Removed {item}.")
            else:
                print("Item not found.")
        elif choice == '3':
            if not inventory:
                print("Inventory empty.")
            else:
                for k, v in inventory.items():
                    print(f"{k}: {v}")
        elif choice == '4':
            break
        else:
            print("Invalid choice.")

    return True

if __name__ == "__main__":
    run_project_84()

